using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Linq;using System.Text.RegularExpressions;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
/* Column and footing schedules of the Bar Bending Schedule (owner, 20 November 2026: "hiwalay ang bbs sa boq. manual schedule ng
   column at footing, parang sa beam ... para di na i-type paulit ulit. pero sa column dapat per elevation siya kasi baka magbago rebar
   per height"): each type is entered once in its schedule - a column mark has one row per level range, because its bars change with
   height - and the members list only gives the ID, the schedule mark and the number of identical members. */
partial class CuttingListForm {
 static readonly string[][] ColumnScheduleCols={new[]{"Mark","MARK"},new[]{"From","FROM LEVEL (m)"},new[]{"To","TO LEVEL (m)"},new[]{"B","WIDTH b (mm)"},new[]{"H","DEPTH h (mm)"},new[]{"Bars","MAIN BARS (e.g. 8-Ø20 or 4-Ø20+4-Ø16)"},new[]{"TieDia","TIE Ø (mm)"},new[]{"TieSpacing","TIE SPACING (mm)"}};
 static readonly string[][] FootingScheduleCols={new[]{"Mark","MARK"},new[]{"L","LENGTH L (m)"},new[]{"B","WIDTH B (m)"},new[]{"T","THICKNESS (mm)"},new[]{"BarsL","BOTTOM BARS PARALLEL TO L (e.g. Ø16@150 or 10-Ø16)"},new[]{"BarsB","BOTTOM BARS PARALLEL TO B"},new[]{"TopL","TOP BARS PARALLEL TO L (optional)"},new[]{"TopB","TOP BARS PARALLEL TO B (optional)"}};
 readonly DataGridView columnSchedule=EditGrid(ColumnScheduleCols),footingSchedule=EditGrid(FootingScheduleCols),columnList=EditGrid(new[]{new[]{"Id","COLUMN ID"},new[]{"Mark","SCHEDULE MARK"},new[]{"Qty","IDENTICAL COLUMNS"}}),footingList=EditGrid(new[]{new[]{"Id","FOOTING ID"},new[]{"Mark","SCHEDULE MARK"},new[]{"Qty","IDENTICAL FOOTINGS"}});
 static DataGridView EditGrid(string[][] cols){var g=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=true,AllowUserToDeleteRows=true,RowHeadersVisible=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize};g.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;
  foreach(var c in cols){if(c[0]=="Mark"&&cols.Length==3){g.Columns.Add(new DataGridViewComboBoxColumn{Name="Mark",HeaderText=c[1],FlatStyle=FlatStyle.Flat,DisplayStyle=DataGridViewComboBoxDisplayStyle.DropDownButton});continue;}g.Columns.Add(c[0],c[1]);}g.DataError+=(s,e)=>{e.ThrowException=false;};return g;}
 /* the inputs above the member schedule grid of the Column / Footing tab */
 Control MemberInputs(string kind){bool column=kind=="Column";var list=column?columnList:footingList;var schedule=column?columnSchedule:footingSchedule;
  var host=new Panel{Dock=DockStyle.Top,Height=210,Padding=new Padding(8,4,8,4)};var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=false};
  var edit=new Button{Text=column?"Column schedules":"Footing schedules",AutoSize=true,Height=34};edit.Click+=(s,e)=>EditSchedule(kind);bar.Controls.Add(edit);
  bar.Controls.Add(new Label{Text=column?"COLUMNS - one row per column (or group of identical columns); the bars per level come from its schedule mark":"FOOTINGS - one row per footing (or group of identical footings)",AutoSize=true,ForeColor=PowTheme.Teal,Font=ModernUi.Strong,Margin=new Padding(10,10,0,0),UseMnemonic=false});
  list.CellValueChanged+=(s,e)=>{if(!filling)Schedule();};list.RowsRemoved+=(s,e)=>{if(!filling)Schedule();};list.CurrentCellDirtyStateChanged+=(s,e)=>{if(list.IsCurrentCellDirty&&list.CurrentCell is DataGridViewComboBoxCell)list.CommitEdit(DataGridViewDataErrorContexts.Commit);};
  list.DefaultValuesNeeded+=(s,e)=>{e.Row.Cells["Qty"].Value="1";};host.Controls.Add(list);host.Controls.Add(bar);RefreshMarks(kind);return host;}
 void RefreshMarks(string kind){var list=kind=="Column"?columnList:footingList;var schedule=kind=="Column"?columnSchedule:footingSchedule;var combo=(DataGridViewComboBoxColumn)list.Columns["Mark"];var marks=schedule.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>Convert.ToString(r.Cells["Mark"].Value).Trim()).Where(m=>m!="").Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(m=>m,StringComparer.OrdinalIgnoreCase).ToList();
  foreach(DataGridViewRow r in list.Rows){if(r.IsNewRow)continue;string m=Convert.ToString(r.Cells["Mark"].Value);if(m!=""&&!marks.Contains(m,StringComparer.OrdinalIgnoreCase))marks.Add(m);}combo.Items.Clear();foreach(var m in marks)combo.Items.Add(m);}
 void EditSchedule(string kind){bool column=kind=="Column";var grid=column?columnSchedule:footingSchedule;var parent=grid.Parent;
  using(var f=new Form{Text=column?"Column schedules":"Footing schedules",Size=new Size(1150,560),StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,ShowInTaskbar=false}){AppBrand.Apply(f);
   var note=new Label{Dock=DockStyle.Top,Height=46,Padding=new Padding(10,8,10,0),ForeColor=PowTheme.Muted,UseMnemonic=false,Text=column?"One row per column mark and level range. A mark whose bars change with height has one row per range (e.g. C1 0.00-3.50 8-Ø20, C1 3.50-7.00 8-Ø16). Bars below the top range lap with the range above (cranked, compression lap); the top range ends in a 90° hook.":"One row per footing mark. Bars as Ø16@150 (spacing) or 10-Ø16 (number of bars); top bars are optional."};
   var done=new Button{Text="Done",DialogResult=DialogResult.OK,Width=110,Height=34,Anchor=AnchorStyles.Right|AnchorStyles.Bottom};var foot=new Panel{Dock=DockStyle.Bottom,Height=50};done.Location=new Point(f.ClientSize.Width-128,8);foot.Controls.Add(done);
   if(parent!=null)parent.Controls.Remove(grid);grid.Dock=DockStyle.Fill;f.Controls.Add(grid);f.Controls.Add(note);f.Controls.Add(foot);f.AcceptButton=done;f.ShowDialog(this);f.Controls.Remove(grid);}
  RefreshMarks(kind);Schedule();}
 static double Num(DataGridViewRow r,string c,string what,string mark){double v;string t=Convert.ToString(r.Cells[c].Value).Trim();if(!double.TryParse(t,NumberStyles.Float,CultureInfo.InvariantCulture,out v)||double.IsNaN(v)||double.IsInfinity(v))throw new Exception(mark+": enter "+what+" as a number.");return v;}
 static string Txt(DataGridViewRow r,string c){return Convert.ToString(r.Cells[c].Value).Trim();}
 /* bar pieces of the scheduled columns and footings */
 List<CutPiece> ScheduledMembers(CutSettings s,List<string> notes){var pieces=new List<CutPiece>();var cfg=s.Config;double cover=s.Cover;
  var options=new EstimateOptions{Cover=cover,LengthConfig=cfg,Fc=cfg.Input.Fc,GradeSmall=cfg.GradeSmall,Grade=cfg.GradeLarge};
  var segments=columnSchedule.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&Txt(r,"Mark")!="").ToList();
  foreach(DataGridViewRow c in columnList.Rows){if(c.IsNewRow)continue;string id=Txt(c,"Id"),mark=Txt(c,"Mark");if(id==""&&mark=="")continue;if(id=="")throw new Exception("Columns: enter the column ID.");int qty=(int)Math.Max(1,Math.Round(Num(c,"Qty","the number of identical columns",id)));
   var rows=segments.Where(r=>Txt(r,"Mark").Equals(mark,StringComparison.OrdinalIgnoreCase)).Select(r=>new{R=r,From=Num(r,"From","the from level",mark),To=Num(r,"To","the to level",mark)}).OrderBy(x=>x.From).ToList();if(rows.Count==0)throw new Exception("Column "+id+": schedule mark "+mark+" is not in the column schedules.");
   int n=0;Func<string> next=()=>"C:"+id+"-"+(++n).ToString(CultureInfo.InvariantCulture);
   for(int k=0;k<rows.Count;k++){var seg=rows[k];double h=seg.To-seg.From;if(h<=0)throw new Exception("Column "+mark+": the to level must be above the from level ("+seg.From+" to "+seg.To+").");double b=Num(seg.R,"B","the width",mark),d=Num(seg.R,"H","the depth",mark);bool above=k<rows.Count-1;string level=seg.From.ToString("0.00",CultureInfo.InvariantCulture)+" to "+seg.To.ToString("0.00",CultureInfo.InvariantCulture)+" m";
    Dictionary<int,int> bars;try{bars=EstimatorEngine.Bars(Txt(seg.R,"Bars").Split('+').Select(x=>x.Trim()).Where(x=>x!="").ToList());}catch(Exception){throw new Exception("Column "+mark+" "+level+": main bars as 8-Ø20 or 4-Ø20+4-Ø16.");}if(bars.Count==0)throw new Exception("Column "+mark+" "+level+": enter the main bars.");
    foreach(var bar in bars.OrderByDescending(x=>x.Key)){int db=bar.Key;double fy=db<=12?cfg.FySmall:cfg.FyLarge;double lap=Math.Ceiling(Math.Max(300,fy<=420?0.071*fy*db:(0.13*fy-24)*db)/10)*10/1000;double hook=cfg.Rounded(cfg.Values(db,false).Cut90)/1000;
     pieces.Add(new CutPiece{Group="Column",Line="Column "+id,BarMark=next(),Location="Main bars, level "+level+(above?" (lap into the range above)":" (top: 90° hook)"),Diameter=db,Grade=BeamCutting.GradeOf(cfg,db),PerLine=bar.Value,Lines=qty,Length=above?h+lap:h-cover/1000+hook,Shape=above?"Cranked lap splice":"90° hook one end",SecB=b,SecH=d});}
    int tieDia=(int)Num(seg.R,"TieDia","the tie diameter",mark);double spacing=Num(seg.R,"TieSpacing","the tie spacing",mark);if(spacing<=0)throw new Exception("Column "+mark+": tie spacing must be positive.");int sets=(int)Math.Ceiling((h*1000-100)/spacing-1e-10)+1;double hoop=HookGeometry.TieParts(b,d,tieDia,2,options).MainHoop;
    pieces.Add(new CutPiece{Group="Column",Line="Column "+id,BarMark=next(),Location="Ties, level "+level+" (@ "+spacing.ToString("0",CultureInfo.InvariantCulture)+" mm)",Diameter=tieDia,Grade=BeamCutting.GradeOf(cfg,tieDia),PerLine=sets,Lines=qty,Length=Math.Ceiling(hoop*1000/25)*25/1000,Shape="Hoop, 135° hooks",SecB=b,SecH=d});}
   if(rows.Count>0&&notes!=null&&rows[0].From>1e-9)notes.Add("Column "+id+": bars start at level "+rows[0].From.ToString("0.00",CultureInfo.InvariantCulture)+" m; starter bars into the footing are not included - add them in the footing or with Add bar.");}
  var fRows=footingSchedule.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&Txt(r,"Mark")!="").ToList();var sources=new List<BbsMemberSource>();
  Func<string,string,FootingBarSpec> spec=(text,what)=>{if(text=="")return new FootingBarSpec();var t=Engine.Normal(text).Replace("#","Ø");var m=Regex.Match(t,@"^Ø?(\d+)@(\d+(\.\d+)?)$");if(m.Success)return new FootingBarSpec{Diameter=int.Parse(m.Groups[1].Value),Spacing=double.Parse(m.Groups[2].Value,CultureInfo.InvariantCulture)};m=Regex.Match(t,@"^(\d+)-Ø?(\d+)$");if(m.Success)return new FootingBarSpec{Diameter=int.Parse(m.Groups[2].Value),Count=int.Parse(m.Groups[1].Value)};throw new Exception(what+": write the bars as Ø16@150 or 10-Ø16.");};
  foreach(DataGridViewRow f in footingList.Rows){if(f.IsNewRow)continue;string id=Txt(f,"Id"),mark=Txt(f,"Mark");if(id==""&&mark=="")continue;if(id=="")throw new Exception("Footings: enter the footing ID.");int qty=(int)Math.Max(1,Math.Round(Num(f,"Qty","the number of identical footings",id)));
   var r=fRows.FirstOrDefault(x=>Txt(x,"Mark").Equals(mark,StringComparison.OrdinalIgnoreCase));if(r==null)throw new Exception("Footing "+id+": schedule mark "+mark+" is not in the footing schedules.");double t=Num(r,"T","the thickness",mark)/1000;
   var bars=new[]{spec(Txt(r,"BarsL"),"Footing "+mark+" bottom bars parallel to L"),spec(Txt(r,"BarsB"),"Footing "+mark+" bottom bars parallel to B"),spec(Txt(r,"TopL"),"Footing "+mark+" top bars parallel to L"),spec(Txt(r,"TopB"),"Footing "+mark+" top bars parallel to B")};
   var take=FootingTakeoff.Calculate(id,mark,Num(r,"L","the length",mark),Num(r,"B","the width",mark),t,1,t+.1,75,true,bars,0,cfg,20,10,100);sources.Add(new BbsMemberSource{Kind="Footing",Id=id,Description=mark,Quantity=qty,Steel=take.Steel});}
  if(sources.Count>0)pieces.AddRange(MemberBbs.Pieces(sources,notes));return pieces;}
 /* saved with the cutting list */
 void WriteMemberSchedules(XmlElement root){var doc=root.OwnerDocument;foreach(var pair in new[]{Tuple.Create("ColumnScheduleRow",columnSchedule),Tuple.Create("ColumnRow",columnList),Tuple.Create("FootingScheduleRow",footingSchedule),Tuple.Create("FootingRow",footingList)})foreach(DataGridViewRow r in pair.Item2.Rows){if(r.IsNewRow)continue;var e=doc.CreateElement(pair.Item1);foreach(DataGridViewColumn c in pair.Item2.Columns)e.SetAttribute(c.Name.ToLowerInvariant(),Convert.ToString(r.Cells[c.Name].Value));root.AppendChild(e);}}
 void ReadMemberSchedules(XmlElement root){foreach(var pair in new[]{Tuple.Create("ColumnScheduleRow",columnSchedule),Tuple.Create("FootingScheduleRow",footingSchedule),Tuple.Create("ColumnRow",columnList),Tuple.Create("FootingRow",footingList)}){pair.Item2.Rows.Clear();if(pair.Item1=="ColumnRow")RefreshMarks("Column");if(pair.Item1=="FootingRow")RefreshMarks("Footing");
   foreach(XmlElement e in root.SelectNodes(pair.Item1)){int i=pair.Item2.Rows.Add();foreach(DataGridViewColumn c in pair.Item2.Columns){string v=e.GetAttribute(c.Name.ToLowerInvariant());var combo=c as DataGridViewComboBoxColumn;if(combo!=null&&v!=""&&!combo.Items.Contains(v))combo.Items.Add(v);pair.Item2.Rows[i].Cells[c.Name].Value=v;}}}}
}
}
